import heapq


class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def merge_two(a, b):
    dummy = ListNode(0)
    tail = dummy
    while a and b:
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a if a else b
    return dummy.next


def mergeKLists(lists):
    if not lists:
        return None
    k = len(lists)
    step = 1
    while step < k:
        for i in range(0, k - step, step * 2):
            lists[i] = merge_two(lists[i], lists[i + step])
        step *= 2
    return lists[0]

